				return true;
			}
			if (p->anchored || (p->flags & 16))
				break;
			start++;
		}
		if (stateful)
			regex->slots[1].number = 0;
		return false;
	}
	size_t length;
	uint16_t *units = regex_input(input, &length);
	uint64_t steps = 0;
	ptrdiff_t *spans = regex_execute(regex, units, length, false, &steps);
	bool result = spans != NULL;
	free(spans);
	free(units);
	return result;
}
static size_t regex_advance(const uint16_t *units, size_t length, size_t at, bool unicode) {
	return unicode && at + 1 < length && high(units[at]) && low(units[at + 1]) ? at + 2 : at + 1;
}
adamic_array *adamic_regex_match(adamic_string *input, adamic_object *regex) {
	const adamic_regex_program *p = regex_program(regex);
	if (!(p->flags & 8))
		return adamic_regex_exec(regex, input);
	regex->slots[1].number = 0;
	adamic_array *result = adamic_array_new(0, true);
	size_t length;
	uint16_t *units = regex_input(input, &length);
	uint64_t steps = 0;
	for (;;) {
		ptrdiff_t *spans = regex_execute(regex, units, length, false, &steps);
		if (spans == NULL)
			break;
		adamic_array_push(result,
						  (adamic_value){.reference = adamic_string_slice(input, (double)spans[0],
																		  (double)spans[1], true)});
		if (spans[0] == spans[1])
			regex->slots[1].number = (double)regex_advance(
				units, length, regex_to_length(regex->slots[1].number), p->flags & 4);
		free(spans);
	}
	free(units);
	if (result->length == 0) {
		adamic_release(result);
		return NULL;
	}
	return result;
}
static const char *const iterator_names[] = {"regex", "input", "done"};
static const bool iterator_references[] = {true, true, false};
static const adamic_shape iterator_shape = {3, iterator_names, iterator_references, NULL};
static void regex_require_global(const adamic_regex_program *p, const char *message) {
	if (!(p->flags & 8))
		adamic_panic(message, strlen(message));
}
adamic_object *adamic_regex_match_all(adamic_string *input, adamic_object *regex) {
	const adamic_regex_program *p = regex_program(regex);
	regex_require_global(
		p, "TypeError: String.prototype.matchAll called with a non-global RegExp argument");
	adamic_object *copy = adamic_regex_new(p, regex->slots[2].reference, regex->slots[3].reference);
	copy->slots[1].number = (double)regex_to_length(regex->slots[1].number);
	adamic_object *iterator = adamic_object_new(&iterator_shape);
	iterator->slots[0].reference = copy;
	iterator->slots[1].reference = adamic_retain(input);
	return iterator;
}
adamic_array *adamic_regex_iterator_step(adamic_object *iterator) {
	if (iterator->slots[2].boolean)
		return NULL;
	adamic_object *regex = iterator->slots[0].reference;
	adamic_string *input = iterator->slots[1].reference;
	adamic_array *result = adamic_regex_exec(regex, input);
	if (result == NULL)
		iterator->slots[2].boolean = true;
	else {
		adamic_string *whole = result->elements[0].reference;
		if (adamic_string_length(whole) == 0) {
			size_t length;
			uint16_t *units = regex_input(input, &length);
			regex->slots[1].number =
				(double)regex_advance(units, length, regex_to_length(regex->slots[1].number),
									  regex_program(regex)->flags & 4);
			free(units);
		}
	}
	return result;
}
static const char *const next_names[] = {"done", "value"};
static const bool next_references[] = {false, true};
static const adamic_shape next_shape = {2, next_names, next_references, NULL};
adamic_object *adamic_regex_next(adamic_object *iterator) {
	adamic_array *value = adamic_regex_iterator_step(iterator);
	adamic_object *result = adamic_object_new(&next_shape);
	result->slots[0].boolean = value == NULL;
	result->slots[1].reference = value;
	return result;
}
double adamic_regex_search(adamic_string *input, adamic_object *regex) {
	double previous = regex->slots[1].number;
	regex->slots[1].number = 0;
	size_t length;
	uint16_t *units = regex_input(input, &length);
	uint64_t steps = 0;
	ptrdiff_t *spans = regex_execute(regex, units, length, false, &steps);
	double result = spans == NULL ? -1 : (double)spans[0];
	free(spans);
	free(units);
	regex->slots[1].number = previous;
	return result;
}
adamic_array *adamic_regex_split(adamic_string *input, adamic_object *regex, double limit_value) {
	adamic_array *result = adamic_array_new(0, true);
	uint32_t limit = (uint32_t)adamic_shift_right_unsigned(limit_value, 0);
	if (limit == 0)
		return result;
	const adamic_regex_program *p = regex_program(regex);
	adamic_object *copy = adamic_regex_new(p, regex->slots[2].reference, regex->slots[3].reference);
	size_t length;
	uint16_t *units = regex_input(input, &length);
	uint64_t steps = 0;
	size_t previous = 0, at = 0;
	if (length == 0) {
		ptrdiff_t *spans = regex_execute(copy, units, length, true, &steps);
		if (spans == NULL)
			adamic_array_push(result, (adamic_value){.reference = adamic_retain(input)});
		free(spans);
		goto finished_split;
	}
	while (at < length) {
		copy->slots[1].number = (double)at;
		ptrdiff_t *spans = regex_execute(copy, units, length, true, &steps);
		if (spans == NULL) {
			at = regex_advance(units, length, at, p->flags & 4);
			continue;
		}
		size_t end = (size_t)spans[1];
		if (end == previous) {
			free(spans);
			at = regex_advance(units, length, at, p->flags & 4);
			continue;
		}
		adamic_array_push(result, (adamic_value){.reference = adamic_string_slice(
													 input, (double)previous, (double)at, true)});
		previous = end;
		if (result->length == limit) {
			free(spans);
			goto finished_split;
		}
		for (size_t k = 1; k <= p->captures; k++) {
			adamic_array_push(
				result, (adamic_value){.reference = spans[2 * k] < 0
														? NULL
														: adamic_string_slice(
															  input, (double)spans[2 * k],
															  (double)spans[2 * k + 1], true)});
			if (result->length == limit) {
				free(spans);
				goto finished_split;
			}
		}
		free(spans);
		at = previous;
	}
	adamic_array_push(result, (adamic_value){.reference = adamic_string_slice(
												 input, (double)previous, (double)length, true)});
finished_split:
	free(units);
	adamic_release(copy);
	return result;
}
static void regex_piece(adamic_array *pieces, adamic_string *input, size_t first, size_t last) {
	adamic_array_push(pieces, (adamic_value){.reference = adamic_string_slice(input, (double)first,
																			  (double)last, true)});
}
static void regex_substitution(adamic_array *pieces, adamic_string *input, size_t input_length,
							   adamic_string *replacement, const uint16_t *text, size_t length,
							   const ptrdiff_t *spans, const adamic_regex_program *p) {
	size_t plain = 0;
	for (size_t at = 0; at < length; at++) {
		if (text[at] != '$' || at + 1 == length)
			continue;
		size_t consumed = 2;
		ptrdiff_t first = -1, last = -1;
		bool special = true;
		uint16_t next = text[at + 1];
		switch (next) {
		case '$':
			first = (ptrdiff_t)at;
			last = (ptrdiff_t)at + 1;
			break;
		case '&':
			first = spans[0];
			last = spans[1];
			break;
		case '`':
			first = 0;
			last = spans[0];
			break;
		case '\'':
			first = spans[1];
			last = (ptrdiff_t)input_length;
			break;
		case '<': {
			if (p->group_count == 0) {
				special = false;
				break;
			}
			size_t end = at + 2;
			while (end < length && text[end] != '>')
				end++;
			if (end == length) {
				special = false;
				break;
			}
			consumed = end - at + 1;
			// Names are compared as strings, retaining UTF-16 spelling for non-ASCII.
			adamic_string *name =
				adamic_string_slice(replacement, (double)(at + 2), (double)end, true);
			for (size_t k = 0; k < p->group_count; k++) {
				size_t bytes = strlen(p->groups[k].name);
				if (name->length == bytes && memcmp(name->bytes, p->groups[k].name, bytes) == 0) {
					for (size_t j = 0; j < p->groups[k].count; j++) {
						size_t id = p->groups[k].captures[j];
						if (spans[2 * id] >= 0) {
							first = spans[2 * id];
							last = spans[2 * id + 1];
						}
					}
				}
			}
			adamic_release(name);
			break;
		}
		default: {
			if (next < '0' || next > '9') {
				special = false;
				break;
			}
			size_t id = next - '0';
			if (at + 2 < length && text[at + 2] >= '0' && text[at + 2] <= '9') {
				size_t pair = id * 10 + text[at + 2] - '0';
				if (pair > 0 && pair <= p->captures) {
					id = pair;
					consumed = 3;
				}
			}
			if (id == 0 || id > p->captures) {
				special = false;
				break;
			}
			first = spans[2 * id];
			last = spans[2 * id + 1];
			break;
		}
		}
		if (!special)
			continue;
		regex_piece(pieces, replacement, plain, at);
		if (first >= 0)
			regex_piece(pieces, next == '$' ? replacement : input, (size_t)first, (size_t)last);
		at += consumed - 1;
		plain = at + 1;
	}
	regex_piece(pieces, replacement, plain, length);
}
adamic_string *adamic_regex_replace(adamic_string *input, adamic_object *regex,
									adamic_string *replacement, bool require_global) {
	const adamic_regex_program *p = regex_program(regex);
	if (require_global)
		regex_require_global(
			p, "TypeError: String.prototype.replaceAll called with a non-global RegExp argument");
	bool global = (p->flags & 8) != 0;
	if (global)
		regex->slots[1].number = 0;
	size_t length, replacement_length;
	uint16_t *units = regex_input(input, &length),
			 *text = regex_input(replacement, &replacement_length);
	uint64_t steps = 0;
	adamic_array *pieces = adamic_array_new(0, true);
	size_t previous = 0;
	for (;;) {
		ptrdiff_t *spans = regex_execute(regex, units, length, false, &steps);
		if (spans == NULL)
			break;
		regex_piece(pieces, input, previous, (size_t)spans[0]);
		regex_substitution(pieces, input, length, replacement, text, replacement_length, spans, p);
		previous = (size_t)spans[1];
		bool empty = spans[0] == spans[1];
		free(spans);
		if (!global)
			break;
		if (empty)
			regex->slots[1].number = (double)regex_advance(
				units, length, regex_to_length(regex->slots[1].number), p->flags & 4);
	}
	regex_piece(pieces, input, previous, length);
	adamic_string *result = adamic_array_join(pieces, &adamic_string_empty, adamic_join_strings);
	adamic_release(pieces);
	free(text);
	free(units);
	return result;
}

stage1/cohere/css/printer_shards_test.go:
package css

import (
	"crypto/sha256"
	"encoding/binary"
	"encoding/json"
	"fmt"
	"io/fs"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"strconv"
	"strings"
	"sync"
	"testing"

	"github.com/system-inc/adamic/internal/buildcache"
	"github.com/system-inc/adamic/internal/childguard"
	"github.com/system-inc/adamic/internal/javascript"
	"github.com/system-inc/adamic/internal/load"
	"github.com/system-inc/adamic/internal/lower"
	"github.com/system-inc/adamic/internal/native"
)

// Each declaration and leaf calls the same recipe through a process-local Once.
// Cached source trees live with their product, never in a declaring test's TempDir.
type cssExecutable struct{ binary, javascript, source string }

var cssOracleOnce [2]sync.Once
var cssOracles [2]string
var cssExecutableOnce [5]sync.Once
var cssExecutables [5]cssExecutable

func cssOracleProduct(t *testing.T, printer bool) string {
	t.Helper()
	index := 0
	if printer {
		index = 1
	}
	cssOracleOnce[index].Do(func() {
		repo, err := filepath.Abs(repository)
		if err != nil {
			t.Fatal(err)
		}
		side, pkg, target := "cohere_side_test.go", "postcss", "adamic_port_side_test.go"
		if printer {
			side, pkg, target = "print_side_test.go", "", "adamic_print_side_test.go"
		}
		sidePath := filepath.Join(repo, "stage1/cohere/css/testdata", side)
		inputs := buildcache.Inputs{
			Name:      "css-printer-oracle-" + strconv.Itoa(index),
			Files:     []string{"stage1/cohere/css/testdata/" + side, "cohere/internal", "cohere/TypeScript/tsc", "cohere/TypeScript-shim", "cohere/go.mod", "cohere/go.sum", "cohere/TypeScript/tsc/go.mod", "cohere/TypeScript/tsc/go.sum"},
			Flags:     []string{"test", "-c", "./internal/format/css/" + pkg},
			Toolchain: []string{buildcache.Tool("go", "version"), runtime.GOOS, runtime.GOARCH},
		}
		directory := buildcache.Product(t, inputs, func(dir string) error {
			overlay, err := json.Marshal(map[string]any{"Replace": map[string]string{filepath.Join(repo, "cohere/internal/format/css", pkg, target): sidePath}})
			if err != nil {
				return err
			}
			overlayPath := filepath.Join(dir, "overlay.json")
			if err := os.WriteFile(overlayPath, overlay, 0644); err != nil {
				return err
			}
			// A product carries no deadline of its own: a cold Go build of cohere's css package can pass 60 s
			// on a compiler-changing candidate, and the build phase's 10-minute ceiling bounds it (rule 10).
			cmd := exec.CommandContext(t.Context(), "go", "test", "-c", "-overlay="+overlayPath, "-o", filepath.Join(dir, "oracle"), "./internal/format/css/"+pkg)
			cmd.Dir = filepath.Join(repo, "cohere")
			output, err := cmd.CombinedOutput()
			if err != nil {
				return fmt.Errorf("Go oracle build: %w\n%s", err, output)
			}
			return nil
		})
		cssOracles[index] = filepath.Join(directory, "oracle")
	})
	// A build that failed inside the Once leaves the path empty for every later caller in this process.
	// Say so, rather than running an empty command.
	if cssOracles[index] == "" {
		t.Fatalf("css oracle product %d unavailable: its build failed earlier in this process (see that test's log)", index)
	}
	return cssOracles[index]
}

// variant -1 is the regular sanitized printer; 0..2 are its mutants;
// variant 3 is the unsanitized printer used by macOS's leaks tool.
func cssPrinterProduct(t *testing.T, variant int) cssExecutable {
	t.Helper()
	index := variant + 1
	cssExecutableOnce[index].Do(func() {
		sanitize := variant != 3
		inputs := buildcache.Inputs{
			Name:      "css-printer-executable-" + strconv.Itoa(variant),
			Files:     []string{"stage1/cohere/css", "stage1/cohere/selector", "stage1/cohere/values", "stage1/cohere/mediaquery", "stage1/cohere/cssstrings", "stage1/cohere/cssnumbers", "internal", "bridge/tsgo", "cohere/policy", "cohere/internal", "cohere/rule_runner", "cohere/go.mod", "cohere/go.sum", "cohere/TypeScript/tsc", "cohere/TypeScript-shim", "go.mod", "go.work"},
			Flags:     append(native.Flags(native.Options{Sanitize: sanitize}), "variant="+strconv.Itoa(variant), "ADAMIC_NATIVE_SPLIT="+os.Getenv("ADAMIC_NATIVE_SPLIT")),
			Toolchain: []string{runtime.Version(), buildcache.Tool("clang", "--version"), runtime.GOOS, runtime.GOARCH},
		}
		directory := buildcache.Product(t, inputs, func(dir string) error {
			var mutation *mutant
			if variant >= 0 && variant < len(printerMutants) {
				mutation = &printerMutants[variant]
			}
			original := portDirectory(t, mutation)
			if err := moveTree(filepath.Dir(original), filepath.Join(dir, "sources")); err != nil {
				return err
			}
			source := filepath.Join(dir, "sources/css/print_main.ts")
			checked, err := load.Load([]string{source})
			if err != nil {
				return err
			}
			program, err := lower.Lower(t.Context(), checked)
			if err != nil {
				return err
			}
			code := native.C(program)
			if err := os.WriteFile(filepath.Join(dir, "main.c"), []byte(code), 0644); err != nil {
				return err
			}
			if err := os.WriteFile(filepath.Join(dir, "main.mjs"), []byte(javascript.JavaScript(program)), 0644); err != nil {
				return err
			}
			return native.Build(code, filepath.Join(dir, "native"), native.Options{Sanitize: sanitize})
		})
		cssExecutables[index] = cssExecutable{filepath.Join(directory, "native"), filepath.Join(directory, "main.mjs"), filepath.Join(directory, "sources/css/print_main.ts")}
	})
	if cssExecutables[index].binary == "" {
		t.Fatalf("css printer product %d unavailable: its build failed earlier in this process (see that test's log)", variant)
	}
	return cssExecutables[index]
}

func TestProduct_CSSPrinterParserOracle(t *testing.T)        { t.Parallel(); cssOracleProduct(t, false) }
func TestProduct_CSSPrinterOracle(t *testing.T)              { t.Parallel(); cssOracleProduct(t, true) }
